func:
let cfg = {
    lift_id: "A",
    floor_name: "1",
    robot_ip: "192.168.10.5",
    robot_port: 502,
    device_ip: "192.168.1.200",
    device_port: 4196,
    pulse_count: 5,
    waveshare: {
        ip: "192.168.1.200",
        port: 4196,
        unit_id: 1,
        door_sensor_input: 0,
        door_sensor_invert: false,
        manual_up_input: 1,
        manual_down_input: 2,
        button_active_low: false,
        up_solenoid_coil: 0,
        down_solenoid_coil: 1,
        up_indicator_coil: 2,
        down_indicator_coil: 3,
        idel_status_coil: 5,
        use_status_coil: 6,
        error_status_coil: 7
    },
    addr: {
        robot_port_502: {
            floor: 0,
            heartbeat: 1,
            lift_status: 2,
            command: 3,
            door: 4,
            call_target: 6
        }
    }
};

try {
    if (msg.payload) {
        let loaded = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
        if (loaded && typeof loaded === 'object') {
            if (loaded.lift_id !== undefined) cfg.lift_id = String(loaded.lift_id).toUpperCase();
            else if (loaded.elevator_name !== undefined) cfg.lift_id = String(loaded.elevator_name).toUpperCase();

            if (loaded.floor_name !== undefined) cfg.floor_name = String(loaded.floor_name);
            if (loaded.robot_ip !== undefined) cfg.robot_ip = String(loaded.robot_ip);
            else if (loaded.remote_ip !== undefined) cfg.robot_ip = String(loaded.remote_ip);

            if (loaded.robot_port !== undefined) cfg.robot_port = Number(loaded.robot_port);
            else if (loaded.remote_port !== undefined) cfg.robot_port = Number(loaded.remote_port);

            if (loaded.pulse_count !== undefined) cfg.pulse_count = Number(loaded.pulse_count);

            if (loaded.waveshare && typeof loaded.waveshare === 'object') {
                Object.assign(cfg.waveshare, loaded.waveshare);
            }
            if (loaded.settings && typeof loaded.settings === 'object') {
                if (loaded.settings.pulse_count !== undefined) cfg.pulse_count = Number(loaded.settings.pulse_count);
            }
        }
    }
} catch(e) {}

// HARD-LOCKED DEVICE IP & PORT
cfg.device_ip = "192.168.1.200";
cfg.device_port = 4196;
cfg.waveshare.ip = "192.168.1.200";
cfg.waveshare.port = 4196;

let offset = (cfg.lift_id === "B") ? 10 : 0;
cfg.addr = {
    robot_port_502: {
        floor: 0 + offset,
        heartbeat: 1 + offset,
        lift_status: 2 + offset,
        command: 3 + offset,
        door: 4 + offset,
        call_target: 6 + offset
    }
};

global.set('lift_config', cfg);

// Initialize LiftConfig structure for multi-floor / multi-lift standard
let liftConfigObj = {
    "A": {
        robot_addr: { floor: 0, heartbeat: 1, status: 2, command: 3, door: 4, target: 6 },
        global_keys: { busy: "lift_busy_A", controller: "lift_ctrl_A" }
    },
    "B": {
        robot_addr: { floor: 10, heartbeat: 11, status: 12, command: 13, door: 14, target: 16 },
        global_keys: { busy: "lift_busy_B", controller: "lift_ctrl_B" }
    }
};
global.set('LiftConfig', liftConfigObj);

let outMsg = {
    topic: "CONFIG_UPDATE",
    payload: {
        type: "config",
        data: cfg
    }
};

let connUpdateMsg = {
    device_ip: "192.168.1.200",
    device_port: 4196,
    robot_ip: cfg.robot_ip,
    robot_port: cfg.robot_port
};

return [outMsg, connUpdateMsg];

if (msg.topic === "SAVE_CONFIG") {
    let rawObj = msg.payload;
    let jsonStr = JSON.stringify(rawObj, null, 4);

    // File Write Msg (Output 1)
    let fileMsg = { payload: jsonStr };

    // Engine Direct Update Msg (Output 2)
    let engineApplyMsg = { topic: "CONFIG_RELOAD", payload: rawObj };

    // Log Msg (Output 3)
    let logMsg = {
        topic: `[Config Saved] Settings updated for Lift ${rawObj.lift_id} (Robot: ${rawObj.robot_ip}:${rawObj.robot_port})`,
        payload: { success: false }
    };

    return [fileMsg, engineApplyMsg, null, logMsg];
} else if (msg.topic === "COMMAND") {
    // Manual Command Msg to Engine (Output 3)
    let cmd = msg.payload.action;
    let engineCmdMsg = { command: cmd, source: "UI_MANUAL" };
    let actName = (cmd === '1') ? 'UP Solenoid' : (cmd === '2') ? 'DOWN Solenoid' : 'Release All';
    let logMsg = {
        topic: `[Manual Command] ${actName} triggered via UI`,
        payload: { success: false }
    };
    return [null, null, engineCmdMsg, logMsg];
}
return null;

let logs = flow.get('activity_logs') || [];
let now = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Bangkok', hour12: false });
let action = "";

if (msg.payload && msg.payload.success === false) {
    action = msg.topic;
} else if (msg.topic) {
    action = msg.topic;
} else if (typeof msg.payload === 'string') {
    action = msg.payload;
} else {
    action = "Elevator Event Logged";
}

logs.unshift({ time: now, action: action });
while (logs.length > 50) logs.pop();
flow.set('activity_logs', logs);

let uiMsg = { payload: logs };
let fileMsg = { payload: `${now},${action}\n` };

return [uiMsg, fileMsg];

const devIp = "192.168.1.200";
const devPort = 4196;
let robIp = msg.robot_ip || "192.168.10.5";
let robPort = Number(msg.robot_port || 502);

let wsConnMsg = {
    payload: {
        connectorType: 'TCP',
        tcpHost: devIp,
        tcpPort: devPort,
        tcpType: 'DEFAULT',
        unitId: 1,
        clientTimeout: 1500,
        reconnectTimeout: 2000
    }
};

let robConnMsg = {
    payload: {
        connectorType: 'TCP',
        tcpHost: robIp,
        tcpPort: robPort,
        tcpType: 'DEFAULT',
        unitId: 1,
        clientTimeout: 1500,
        reconnectTimeout: 2000
    }
};

return [wsConnMsg, robConnMsg];

// === ดึงการตั้งค่า Dynamic จากระบบ ===
let raw_cfg = global.get("lift_config") || {};
const LIFT_ID = String(raw_cfg.lift_id || "A").toUpperCase();
const FLOOR = Number(raw_cfg.floor_name || 1);
const MAX_PULSES = Number(raw_cfg.pulse_count || 3);
const MANUAL_COOLDOWN_MS = 2000; // ล็อคป้องกันการกดรัว / กดค้าง 2 วินาที
// =========================================================

let config = global.get("LiftConfig");
if (!config) {
    config = {
        "A": {
            robot_addr: { floor: 0, heartbeat: 1, status: 2, command: 3, door: 4, target: 6 },
            global_keys: { busy: "lift_busy_A", controller: "lift_ctrl_A" }
        },
        "B": {
            robot_addr: { floor: 10, heartbeat: 11, status: 12, command: 13, door: 14, target: 16 },
            global_keys: { busy: "lift_busy_B", controller: "lift_ctrl_B" }
        }
    };
    global.set("LiftConfig", config);
}
let conf = config[LIFT_ID] || (LIFT_ID === "B" ? config["B"] : config["A"]);

let now = Date.now();

// -------------------------------------------------------------
// 0. ตรวจจับการเปลี่ยน IP / Config Reload -> รีเซ็ต Connection ทันที
// -------------------------------------------------------------
if (msg.topic === "CONFIG_RELOAD" || msg.topic === "SAVE_CONFIG" || msg.topic === "CONFIG_UPDATE") {
    context.set("last_ws_rx", 0);
    context.set("prev_is_connected", false);
    context.set("auto_state", "IDLE");
    global.set("robot_floor_" + LIFT_ID, FLOOR);
}

// ตัวแปรสถานะ
let state = context.get("state") || { up: false, down: false, prev_u: false, prev_d: false };
let is_busy = global.get(conf.global_keys.busy) || false;
let ctrl = global.get(conf.global_keys.controller) || "";
let robot_target = global.get("robot_target_" + LIFT_ID) || 0;

// Cooldown Timers สำหรับ Manual Buttons
let last_manual_up = context.get("last_manual_up") || 0;
let last_manual_down = context.get("last_manual_down") || 0;

// Pulse State Machine สำหรับโหมด Auto
let auto_state = context.get("auto_state") || "IDLE"; // IDLE, CALLING, PULSING, DONE, COOLDOWN
let current_pulse = context.get("current_pulse") || 0;
let pulse_step = context.get("pulse_step") || "ON";
let pulse_timer = context.get("pulse_timer") || 0;
let is_recovering = context.get("is_recovering") || false;
let last_pulse_step = context.get("last_pulse_step") || "";

let trigger_up = false, trigger_down = false, light_clr = false;
let out_hw = null, out_rob = null, out_dbg = null;
let log_entries = [];

function addLog(text) {
    log_entries.push(text);
}

// -------------------------------------------------------------
// 0.1 คำสั่งจาก Manual UI Dashboard / API (พร้อมระบบ Cooldown 2s)
// -------------------------------------------------------------
if (msg.command !== undefined) {
    let c = String(msg.command).trim();
    if (c === "1" || c === "UP" || c === "CALL_UP" || c === "call" || c === "open") {
        if (now - last_manual_up >= MANUAL_COOLDOWN_MS) {
            state.up = true;
            trigger_up = true;
            last_manual_up = now;
            context.set("last_manual_up", now);
            addLog(`[Manual UI] Lift ${LIFT_ID} Called UP (Coil 0 Solenoid + Coil 2 Light)`);
        } else {
            addLog(`[Manual Rate-Limit] UP button ignored (Cooldown active: ${Math.ceil((MANUAL_COOLDOWN_MS - (now - last_manual_up)) / 1000)}s left)`);
        }
    } else if (c === "2" || c === "DOWN" || c === "CALL_DOWN") {
        if (now - last_manual_down >= MANUAL_COOLDOWN_MS) {
            state.down = true;
            trigger_down = true;
            last_manual_down = now;
            context.set("last_manual_down", now);
            addLog(`[Manual UI] Lift ${LIFT_ID} Called DOWN (Coil 1 Solenoid + Coil 3 Light)`);
        } else {
            addLog(`[Manual Rate-Limit] DOWN button ignored (Cooldown active: ${Math.ceil((MANUAL_COOLDOWN_MS - (now - last_manual_down)) / 1000)}s left)`);
        }
    } else if (c === "0" || c === "STOP" || c === "CLOSE" || c === "RELEASE") {
        state.up = false;
        state.down = false;
        light_clr = true;
        auto_state = "IDLE";
        current_pulse = 0;
        is_recovering = false;
        context.set("auto_state", "IDLE");
        context.set("current_pulse", 0);
        context.set("is_recovering", false);
        addLog(`[Manual UI] Lift ${LIFT_ID} All Relays Released / Stopped`);
    }
}

// -------------------------------------------------------------
// 0.2 ตรวจจับข้อมูล Holding Registers จาก Robot (Port 502)
// -------------------------------------------------------------
if (msg.topic === "ROBOT_REGISTERS" || (msg.payload && Array.isArray(msg.payload) && typeof msg.payload[0] === "number")) {
    let target_addr = conf.robot_addr.target || (LIFT_ID === "B" ? 16 : 6);
    if (msg.payload.length > target_addr) {
        let incoming_target = Number(msg.payload[target_addr] || 0);
        if (auto_state !== "COOLDOWN") {
            robot_target = incoming_target;
            global.set("robot_target_" + LIFT_ID, robot_target);
        }
    }
}

// -------------------------------------------------------------
// ตรวจสอบ Inputs จากบอร์ด Waveshare (Port 4196) & อัปเดต Heartbeat Watchdog
// -------------------------------------------------------------
let inputs = msg.payload;
let is_ws_inputs = (msg.topic === "WAVESHARE_INPUTS") || (Array.isArray(inputs) && typeof inputs[0] === "boolean");

let door_open = context.get("prev_door") || false;
let btn_up = false;
let btn_down = false;

if (is_ws_inputs && Array.isArray(inputs) && inputs.length >= 3) {
    context.set("last_ws_rx", now);
    let invert_door = (raw_cfg.waveshare && raw_cfg.waveshare.door_sensor_invert) === true;
    if (invert_door) {
        door_open = (inputs[0] === 1 || inputs[0] === true);
    } else {
        door_open = (inputs[0] === 0 || inputs[0] === false);
    }
    btn_up = Boolean(inputs[1]);
    btn_down = Boolean(inputs[2]);
}

// ตรวจสอบสถานะการเชื่อมต่อ (Connected vs Disconnected)
let last_rx = context.get("last_ws_rx") || 0;
let is_connected = (now - last_rx) < 2500 && last_rx > 0;
let prev_conn = context.get("prev_is_connected");

if (is_connected !== prev_conn) {
    context.set("prev_is_connected", is_connected);
    if (!is_connected) {
        addLog(`[COMMUNICATION ERROR] Disconnected from Device (${raw_cfg.device_ip || '192.168.1.200'}:${raw_cfg.device_port || 4196})`);
    } else {
        addLog(`[COMMUNICATION SUCCESS] Connected to Device (${raw_cfg.device_ip || '192.168.1.200'}:${raw_cfg.device_port || 4196})`);
    }
}

// --- 1. โหมด Manual (ปุ่มกดหน้าบานลิฟต์ พร้อมระบบกันกดค้าง & กดรัว 2 วินาที) ---
if (is_connected && !(is_busy && ctrl === "ROBOT")) {
    if (btn_up && !state.prev_u) {
        if (now - last_manual_up >= MANUAL_COOLDOWN_MS) {
            state.up = true;
            trigger_up = true;
            last_manual_up = now;
            context.set("last_manual_up", now);
            addLog(`[Physical Button] UP Button (Input 1) Pressed -> Lift ${LIFT_ID}`);
        } else {
            addLog(`[Rate-Limit] Physical UP button press ignored (2s cooldown)`);
        }
    }
    if (btn_down && !state.prev_d) {
        if (now - last_manual_down >= MANUAL_COOLDOWN_MS) {
            state.down = true;
            trigger_down = true;
            last_manual_down = now;
            context.set("last_manual_down", now);
            addLog(`[Physical Button] DOWN Button (Input 2) Pressed -> Lift ${LIFT_ID}`);
        } else {
            addLog(`[Rate-Limit] Physical DOWN button press ignored (2s cooldown)`);
        }
    }
}
state.prev_u = btn_up;
state.prev_d = btn_down;

// --- 2. โหมด Auto พร้อมระบบ Pulse Count & Error Recovery ---
if (is_connected) {
    let target_floor_num = Number(robot_target || 0);

    // ปลด Cooldown หลังจบงาน 2 วินาที (ป้องกัน Double-Trigger)
    if (auto_state === "COOLDOWN") {
        if (now - pulse_timer >= 2000) {
            auto_state = "IDLE";
            context.set("auto_state", "IDLE");
        }
    }

    // หุ่นยนต์สั่งเรียกลิฟต์เป้าหมาย
    if (target_floor_num === FLOOR && target_floor_num > 0 && auto_state === "IDLE" && (!is_busy || ctrl === "ROBOT")) {
        global.set(conf.global_keys.busy, true);
        global.set(conf.global_keys.controller, "ROBOT");

        // --- คำนวณทิศทางการเรียกลิฟต์ (UP / DOWN) ---
        let current_lift_floor = global.get("robot_floor_" + LIFT_ID) || FLOOR;
        let call_dir = "UP";

        if (current_lift_floor === 1) {
            call_dir = "UP"; // ชั้น 1 สั่งขึ้นได้อย่างเดียว
        } else if (current_lift_floor === 4) {
            call_dir = "DOWN"; // ชั้น 4 สั่งลงได้อย่างเดียว
        } else {
            // ชั้นอื่นๆ (เช่น 2, 3) อิงจากชั้นปัจจุบันและเป้าหมาย
            if (target_floor_num >= current_lift_floor) {
                call_dir = "UP";
            } else {
                call_dir = "DOWN";
            }
        }

        // บันทึกทิศทางไว้ให้โหมด PULSING ใช้ต่อ
        context.set("auto_call_dir", call_dir);
        // ---------------------------------------

        if (door_open) {
            auto_state = "PULSING";
            current_pulse = 0;
            pulse_step = "ON";
            last_pulse_step = "";
            pulse_timer = now;
            is_recovering = false;
            addLog(`[Auto Robot] Door already OPEN at Floor ${FLOOR} -> Starting ${MAX_PULSES} Pulses (Direction: ${call_dir})`);
        } else {
            auto_state = "CALLING";
            current_pulse = 0;
            is_recovering = false;

            // สั่งงานรีเลย์ตามทิศทางที่ประมวลผลไว้
            if (call_dir === "UP") {
                state.up = true;
                trigger_up = true;
                addLog(`[Auto Robot] Target Floor ${FLOOR} (Current Lift is at ${current_lift_floor}) -> Calling Lift UP`);
            } else {
                state.down = true;
                trigger_down = true;
                addLog(`[Auto Robot] Target Floor ${FLOOR} (Current Lift is at ${current_lift_floor}) -> Calling Lift DOWN`);
            }
        }
    } else if (target_floor_num !== FLOOR && auto_state === "IDLE") {
        auto_state = "IDLE";
        is_recovering = false;
    }

    // เมื่อลิฟต์มาถึงและประตูเปิดออก -> เริ่มเข้าสู่กระบวนการ Pulse
    if (auto_state === "CALLING" && door_open) {
        auto_state = "PULSING";
        current_pulse = 0;
        pulse_step = "ON";
        last_pulse_step = "";
        pulse_timer = now;
        state.up = false;
        state.down = false; // เคลียร์สถานะ manual relay
        light_clr = true;
        let c_dir = context.get("auto_call_dir") || "UP";
        addLog(`[Auto Robot] Lift ${LIFT_ID} Door OPEN detected -> Starting Hold-Open Sequence (${MAX_PULSES} Pulses, Dir: ${c_dir})`);
    }

    // การทำงานในรอบ Pulse Sequence
    if (auto_state === "PULSING") {
        // ดึงทิศทางที่เคยตัดสินใจไว้ในสถานะ CALLING
        let current_dir = context.get("auto_call_dir") || "UP";
        // ถ้าเป็น UP ให้พัลส์ที่ Coil 0, ถ้าเป็น DOWN ให้พัลส์ที่ Coil 1
        let pulse_on_val = (current_dir === "DOWN") ? [false, true, false, false] : [true, false, false, false];
        let pulse_off_val = [false, false, false, false];

        if (!door_open) {
            if (!is_recovering) {
                is_recovering = true;
                pulse_timer = now;
                last_pulse_step = "";
                addLog(`[MISSION ERROR] Elevator ${LIFT_ID} CLOSED prematurely after pulse ${current_pulse}/${MAX_PULSES}!`);
            }

            let elapsed = now - pulse_timer;
            if (elapsed < 1000) {
                out_hw = out_hw || [];
                out_hw.push({ payload: { value: pulse_on_val, fc: 15, unitid: 1, address: 0, quantity: 4 } });
            } else if (elapsed < 1500) {
                out_hw = out_hw || [];
                out_hw.push({ payload: { value: pulse_off_val, fc: 15, unitid: 1, address: 0, quantity: 4 } });
            } else {
                pulse_timer = now;
            }

        } else {
            if (is_recovering) {
                is_recovering = false;
                pulse_step = "ON";
                last_pulse_step = "";
                pulse_timer = now;
                addLog(`[RECOVERY SUCCESS] Lift ${LIFT_ID} door REOPENED! Resuming pulse ${current_pulse + 1}/${MAX_PULSES}`);
            }

            let elapsed = now - pulse_timer;
            if (pulse_step === "ON") {
                if (last_pulse_step !== `ON_${current_pulse}`) {
                    last_pulse_step = `ON_${current_pulse}`;
                    out_hw = out_hw || [];
                    out_hw.push({ payload: { value: pulse_on_val, fc: 15, unitid: 1, address: 0, quantity: 4 } });
                }

                if (elapsed >= 1000) {
                    current_pulse++;
                    pulse_step = "OFF";
                    pulse_timer = now;
                    addLog(`[Pulse Engine] Lift ${LIFT_ID} Pulse ${current_pulse}/${MAX_PULSES} Completed (Dir: ${current_dir})`);
                }
            } else {
                if (last_pulse_step !== `OFF_${current_pulse}`) {
                    last_pulse_step = `OFF_${current_pulse}`;
                    out_hw = out_hw || [];
                    out_hw.push({ payload: { value: pulse_off_val, fc: 15, unitid: 1, address: 0, quantity: 4 } });
                }

                if (elapsed >= 500) {
                    if (current_pulse >= MAX_PULSES) {
                        auto_state = "COOLDOWN";
                        current_pulse = 0;
                        is_recovering = false;
                        pulse_timer = now;

                        robot_target = 0;
                        global.set("robot_target_" + LIFT_ID, 0);

                        out_rob = out_rob || [];
                        out_rob.push({ payload: { value: 0, fc: 6, unitid: 1, address: conf.robot_addr.target, quantity: 1 } });
                        global.set(conf.global_keys.busy, false);
                        global.set(conf.global_keys.controller, "");
                        addLog(`[MISSION DONE] Completed exactly ${MAX_PULSES} pulses -> Auto Mission Finished for Lift ${LIFT_ID}`);
                    } else {
                        pulse_step = "ON";
                        pulse_timer = now;
                    }
                }
            }
        }
    }
}

context.set("auto_state", auto_state);
context.set("current_pulse", current_pulse);
context.set("pulse_step", pulse_step);
context.set("pulse_timer", pulse_timer);
context.set("is_recovering", is_recovering);
context.set("last_pulse_step", last_pulse_step);

// --- 3. ประตูเปิดในโหมด Manual (เคลียร์สถานะ) ---
if (door_open && (state.up || state.down) && auto_state === "IDLE") {
    state.up = false;
    state.down = false;
    light_clr = true;
    addLog(`[Door Event] Lift ${LIFT_ID} Door OPENED -> Cleared Manual Call`);
}

// --- 4. สั่งงานฮาร์ดแวร์ลิฟต์เมื่อมีการกดปุ่ม Manual / สั่งเรียก Auto ---
if ((trigger_up || trigger_down || light_clr) && auto_state !== "PULSING" && is_connected) {
    let coils_on = [trigger_up, trigger_down, state.up, state.down];
    out_hw = out_hw || [];
    out_hw.push({ payload: { value: coils_on, fc: 15, unitid: 1, address: 0, quantity: 4 } });

    if (trigger_up || trigger_down) {
        setTimeout(() => {
            let st = context.get("state") || { up: false, down: false };
            node.send([{ payload: { value: [false, false, st.up, st.down], fc: 15, unitid: 1, address: 0, quantity: 4 } }, null, null, null]);
        }, 1000);
    }
}

// --- 5. อัปเดตข้อมูลหุ่นยนต์ ---
let prev_door = context.get("prev_door");
if (door_open !== prev_door && is_connected) {
    context.set("prev_door", door_open);
    let curr_fl = global.get("robot_floor_" + LIFT_ID) || FLOOR;
    if (door_open) {
        curr_fl = FLOOR;
        global.set("robot_floor_" + LIFT_ID, curr_fl);
    }
    let d_stat = door_open ? 1 : 2;
    out_rob = out_rob || [];
    out_rob.push({ payload: { value: curr_fl, fc: 6, unitid: 1, address: conf.robot_addr.floor, quantity: 1 } });
    out_rob.push({ payload: { value: d_stat, fc: 6, unitid: 1, address: conf.robot_addr.status, quantity: 1 } });
    out_rob.push({ payload: { value: d_stat, fc: 6, unitid: 1, address: conf.robot_addr.door, quantity: 1 } });
}

// --- 6. ล็อคระบบ (Manual) ร่วมกับชั้นอื่น & คุมไฟสถานะ LED ---
let manual_track = global.get("manual_track_" + LIFT_ID) || { 1: false, 2: false, 3: false, 4: false };
manual_track[FLOOR] = (state.up || state.down);
global.set("manual_track_" + LIFT_ID, manual_track);

let any_manual = manual_track[1] || manual_track[2] || manual_track[3] || manual_track[4];
if (any_manual) {
    global.set(conf.global_keys.busy, true);
    global.set(conf.global_keys.controller, "MANUAL");
} else if (ctrl === "MANUAL") {
    global.set(conf.global_keys.busy, false);
    global.set(conf.global_keys.controller, "");
}

// กำหนดสถานะไฟ Tower Lamp
let led = "NORMAL";
if (!is_connected || is_recovering || global.get("lift_is_error")) {
    led = "ERROR";
} else if (door_open || auto_state === "CALLING" || auto_state === "PULSING" || any_manual) {
    led = "ACTIVE";
}

if (led !== context.get("prev_led") && is_connected) {
    context.set("prev_led", led);
    let val = (led === "NORMAL") ? [true, false, false] : (led === "ACTIVE") ? [false, true, false] : [false, false, true];
    out_hw = out_hw || [];
    out_hw.push({ payload: { value: val, fc: 15, unitid: 1, address: 5, quantity: 3 } });
}

// --- 7. จัดรูปแบบสำหรับ Dashboard UI Telemetry ---
let current_robot_floor = global.get("robot_floor_" + LIFT_ID) || FLOOR;
let telem_payload = {
    type: "telemetry",
    floor: current_robot_floor,
    door_is_open: door_open,
    door_text: !is_connected ? "OFFLINE" : (door_open ? "OPEN" : "CLOSED"),
    door_color: !is_connected ? "grey" : (door_open ? "success" : "error"),
    state: !is_connected ? "DISCONNECTED" : (is_recovering ? "ERROR RECOVERY" : (auto_state === "PULSING" ? `PULSING (${current_pulse}/${MAX_PULSES})` : (led === "NORMAL" ? "IDLE" : led))),
    pulse_progress: auto_state === "PULSING" ? `${current_pulse}/${MAX_PULSES}` : "",
    is_recovering: is_recovering,
    is_connected: is_connected,
    lift_id: LIFT_ID,
    config: raw_cfg
};
out_dbg = { payload: telem_payload };

context.set("state", state);

// Dispatch outputs
if (out_hw !== null) {
    for (let hw_msg of out_hw) {
        node.send([hw_msg, null, null, null]);
    }
}

if (out_rob !== null) {
    for (let rob_msg of out_rob) {
        node.send([null, rob_msg, null, null]);
    }
}

node.send([null, null, out_dbg, null]);

if (log_entries.length > 0) {
    for (let txt of log_entries) {
        node.send([null, null, null, { topic: txt, payload: { success: true } }]);
    }
}

return null;

let cfg = global.get('lift_config') || { lift_id: "A", floor_name: "1", robot_ip: "192.168.10.5", robot_port: 502, device_ip: "192.168.1.200", device_port: 4196, pulse_count: 5 };
let now = new Date().toISOString();

msg.statusCode = 200;
msg.payload = {
    success: true,
    lift_id: cfg.lift_id || 'A',
    floor: Number(cfg.floor_name || 1),
    robot_ip: cfg.robot_ip || '',
    robot_port: cfg.robot_port || 502,
    device_ip: cfg.device_ip || '192.168.1.200',
    device_port: cfg.device_port || 4196,
    pulse_count: cfg.pulse_count || 5,
    timestamp: now
};
return msg;

let p = msg.payload || {};
let action = p.action || p.command || "1";
let cfg = global.get('lift_config') || { lift_id: "A" };

let res = {
    statusCode: 200,
    payload: {
        success: true,
        message: `Command '${action}' dispatched to Lift ${cfg.lift_id}.`
    }
};

let cmdMsg = { command: action, source: "API" };
let logMsg = { topic: `[API Command] Sent '${action}' to Lift ${cfg.lift_id}`, payload: { success: true } };

return [res, cmdMsg, logMsg];

let d = new Date();
d.setHours(d.getHours() + 7);
let dateStr = d.toISOString().split('T')[0];
msg.headers = {
    "Content-Disposition": `attachment; filename="elevator_log_${dateStr}.csv"`,
    "Content-Type": "text/csv"
};
return msg;
